double Num(const TSharedPtr<FJsonObject>& O,const TCHAR* K,double F=0){double V;return O.IsValid()&&O->TryGetNumberField(K,V)?V:F;}
FString Str(const TSharedPtr<FJsonObject>& O,const TCHAR* K,const FString& F=TEXT("—")){FString V;return O.IsValid()&&O->TryGetStringField(K,V)?V:F;}
TSharedPtr<FJsonObject> Obj(const TSharedPtr<FJsonObject>& O,const TCHAR* K){const TSharedPtr<FJsonObject>* V;return O.IsValid()&&O->TryGetObjectField(K,V)?*V:MakeShared<FJsonObject>();}
FString Dec(double V,int N=2){FNumberFormattingOptions O;O.SetMinimumFractionalDigits(N);O.SetMaximumFractionalDigits(N);return FText::AsNumber(V,&O).ToString();}
FString Money(double V){return Dec(V)+TEXT(" USDT");}
FSlateFontInfo RuntimeFont(int Size){static TSharedPtr<const FCompositeFont> Light=MakeShared<FCompositeFont>(FName(TEXT("Default")),FPaths::EngineContentDir()/TEXT("Slate/Fonts/Roboto-Light.ttf"),EFontHinting::Default,EFontLoadingPolicy::LazyLoad);static TSharedPtr<const FCompositeFont> Regular=MakeShared<FCompositeFont>(FName(TEXT("Default")),FPaths::EngineContentDir()/TEXT("Slate/Fonts/Roboto-Regular.ttf"),EFontHinting::Default,EFontLoadingPolicy::LazyLoad);return FSlateFontInfo(Size>=18?Light:Regular,Size,FName(TEXT("Default")));}
TSharedRef<STextBlock> Text(const FString& V,int Size=14,FLinearColor Color=Ink){return SNew(STextBlock).Text(FText::FromString(V)).Font(RuntimeFont(Size)).ColorAndOpacity(Color).AutoWrapText(true);}
TSharedRef<SWidget> Section(const TSharedRef<SWidget>& Body,FMargin Padding=FMargin(18)){return SNew(SOverlay)+SOverlay::Slot()[SNew(SBackgroundBlur).BlurStrength(18.f).bApplyAlphaToBlur(false).CornerRadius(FVector4(16,16,16,16))]+SOverlay::Slot()[SNew(SBorder).BorderImage(&PanelBrush).Padding(Padding)[Body]];}
TSharedRef<SWidget> Rail(const TSharedRef<SWidget>& Body,FMargin Padding=FMargin(18)){return SNew(SBox).Padding(Padding)[Body];}
TSharedRef<SWidget> Pair(const FString& Label,const FString& Value,int Size=14){return SNew(SHorizontalBox)+SHorizontalBox::Slot().FillWidth(1).VAlign(VAlign_Center)[Text(Label,Size,Muted)]+SHorizontalBox::Slot().AutoWidth().Padding(14,0,0,0)[Text(Value,Size,Ink)];}
TSharedRef<SWidget> Rule(){return SNew(SSeparator).ColorAndOpacity(FLinearColor(.35,.58,.49,.32));}
TArray<FVector2D> Points(const TSharedPtr<FJsonObject>& O,const TCHAR* K,int Window){const TArray<TSharedPtr<FJsonValue>>* A;TArray<FVector2D> Result;if(O.IsValid()&&O->TryGetArrayField(TEXT("equityHistory"),A)){int First=Window>0?FMath::Max(0,A->Num()-Window):0;for(int I=First;I<A->Num();I++)Result.Add(FVector2D(Num((*A)[I]->AsObject(),TEXT("day"),I+1),Num((*A)[I]->AsObject(),K)));}return Result;}
FString Label(const FString& K){static TMap<FString,FString> L={{TEXT("kind"),TEXT("Typ")},{TEXT("category"),TEXT("Kategorie")},{TEXT("description"),TEXT("Verhalten")},{TEXT("parameters"),TEXT("Parameter")},{TEXT("causality"),TEXT("Zeitliche Verfügbarkeit")},{TEXT("inputs"),TEXT("Benötigte Beobachtungen")},{TEXT("lookback"),TEXT("Historischer Datenbedarf")},{TEXT("confirmationLag"),TEXT("Bestätigungsverzögerung")},{TEXT("observableAt"),TEXT("Signal verfügbar ab")},{TEXT("executionAt"),TEXT("Früheste Ausführung")},{TEXT("retrospectivePlot"),TEXT("Historische Markierungen")},{TEXT("futureRequired"),TEXT("Zukünftige Daten erforderlich")},{TEXT("verification"),TEXT("Prüfstatus")},{TEXT("source"),TEXT("Herkunft")},{TEXT("sourceFiles"),TEXT("Quellnachweise")},{TEXT("caveat"),TEXT("Forschungsgrenze")},{TEXT("license"),TEXT("Quellhinweis")},{TEXT("channelLookback"),TEXT("Lookback · Renko-Bars")},{TEXT("hardSlPct"),TEXT("Quell-Stopp · %")},{TEXT("mandatoryHardSlPct"),TEXT("Pflicht-Schutzstopp · %")},{TEXT("ttpTrailPct"),TEXT("Trailing Take Profit · %")},{TEXT("partialTpPct"),TEXT("Teilgewinn-Schwelle · %")},{TEXT("waitMinSlPct"),TEXT("WAIT-Stopp mindestens · %")},{TEXT("waitMaxSlPct"),TEXT("WAIT-Stopp höchstens · %")},{TEXT("fills"),TEXT("Ausführungen")},{TEXT("observedDays"),TEXT("Gemessene Handelstage")},{TEXT("netPnl"),TEXT("Nettoergebnis · USDT")},{TEXT("fees"),TEXT("Gebühren · USDT")},{TEXT("maxDrawdownPct"),TEXT("Größter Tagesend-Rückgang · %")},{TEXT("parents"),TEXT("Eltern")},{TEXT("rootAccess"),TEXT("Wurzelzugang")},{TEXT("leafCapture"),TEXT("Blattaufnahme")},{TEXT("waterResponse"),TEXT("Wasserreaktion")},{TEXT("sunResponse"),TEXT("Sonnenreaktion")},{TEXT("rootLeafCost"),TEXT("Kosten der Genkombination")},{TEXT("netGrowth"),TEXT("Biomasseänderung heute")},{TEXT("vigorDelta"),TEXT("Vitalitätsänderung")}};if(auto V=L.Find(K))return *V;FString R;for(int I=0;I<K.Len();I++){if(I&&FChar::IsUpper(K[I]))R+=TEXT(" ");R.AppendChar(I?K[I]:FChar::ToUpper(K[I]));}return R;}
void AddObject(const TSharedPtr<SVerticalBox>& Box,const TSharedPtr<FJsonObject>& O,int Depth=0){if(!O.IsValid()||Depth>5)return;for(auto Pair:O->Values){FString K(*Pair.Key);if(K==TEXT("schemaVersion")||K==TEXT("snippet")||K==TEXT("id"))continue;auto V=Pair.Value;if(V->Type==EJson::Object){Box->AddSlot().AutoHeight().Padding(0,14,0,5)[Text(Label(K),16,Mint)];AddObject(Box,V->AsObject(),Depth+1);}else{FString Value;if(V->Type==EJson::Array){if(K==TEXT("equityHistory"))Value=FString::Printf(TEXT("%d gemessene Tageswerte · im Diagramm"),V->AsArray().Num());else for(auto Item:V->AsArray()){if(!Value.IsEmpty())Value+=TEXT(" · ");if(Item->Type==EJson::String)Value+=Item->AsString();else if(Item->Type==EJson::Object)Value+=Str(Item->AsObject(),TEXT("name"),Str(Item->AsObject(),TEXT("id")));}}else if(V->Type==EJson::Number)Value=Dec(V->AsNumber(),K==TEXT("fills")||K==TEXT("observedDays")||K==TEXT("channelLookback")?0:4);else if(V->Type==EJson::Boolean)Value=V->AsBool()?TEXT("Ja"):TEXT("Nein");else if(V->Type==EJson::String)Value=V->AsString();else Value=TEXT("—");if(Value==TEXT("tested"))Value=TEXT("Mit Kausalitätstests geprüft");Box->AddSlot().AutoHeight().Padding(0,8,0,2)[Text(Label(K),13,Muted)];Box->AddSlot().AutoHeight().Padding(0,0,0,5)[Text(Value,15)];}}}
