void SCloudgardenSlateHUD::Construct(const FArguments& Args){Owner=Args._OwnerHUD;Portrait=SNew(SCloudgardenPlantPortrait).OwnerHUD(Owner.Get());ChildSlot[Build(1440)];}
ACloudgardenController* SCloudgardenSlateHUD::Controller() const {return Owner.IsValid()?Cast<ACloudgardenController>(Owner->GetOwningPlayerController()):nullptr;}
ACloudgardenMode* SCloudgardenSlateHUD::Mode() const {return Owner.IsValid()?Cast<ACloudgardenMode>(Owner->GetWorld()->GetAuthGameMode()):nullptr;}
FReply SCloudgardenSlateHUD::Act(const FString& Action){if(auto PC=Controller()){if(Action.StartsWith(TEXT("drawer"))){DrawerTab=FCString::Atoi(*Action.Mid(6));PC->ShowLibrary=DrawerTab==3;PC->ShowDetails=DrawerTab!=3;}else{if(Action==TEXT("details"))DrawerTab=0;PC->HandleHUDAction(Action);}}LastKey.Empty();return FReply::Handled();}
FVector2D SCloudgardenSlateHUD::CalloutPosition()const{auto PC=Controller();if(!PC||!IsValid(PC->Selected))return FVector2D(-1000,-1000);FVector Origin,Extent;PC->Selected->GetActorBounds(false,Origin,Extent);FVector2D Screen;if(!PC->ProjectWorldLocationToScreen(Origin+FVector(0,0,Extent.Z+18),Screen,true))return FVector2D(-1000,-1000);int PX,PY;PC->GetViewportSize(PX,PY);const FVector2D Size=GetCachedGeometry().GetLocalSize();Screen.X*=Size.X/FMath::Max(1,PX);Screen.Y*=Size.Y/FMath::Max(1,PY);return FVector2D(FMath::Clamp(Screen.X+24,20.,FMath::Max(20.,Size.X-240)),FMath::Clamp(Screen.Y-18,85.,FMath::Max(85.,Size.Y-(PC->ShowDetails||PC->ShowLibrary?400:190))));}

